## Rendering and (atomically) writing the generated launcher scripts.
##
## The launcher is deliberately bash: it has to iterate an argument array and
## conditionally rewrite arguments before `exec`, and a Python interpreter
## start-up of that order is not something you want on every invocation of,
## say, `git`.
##
## Integrity markers
## -----------------
## Every generated file starts with the same two lines the original Python
## tool emitted:
##
##     #!/bin/bash
##     # AUTOGENERATED FILE! DO NOT EDIT!
##
## which serves two purposes: a human who opens the file knows not to edit it,
## and this program can recognise *its own* previous output (including output
## produced by the Python original) so it can clean up stale launchers without
## deleting files it did not create.

import std/[os, strutils]

const
  GeneratedMarker* = "# AUTOGENERATED FILE! DO NOT EDIT!"

  ## Placeholders substituted into the template.  They use `{{ }}` so that they
  ## cannot collide with the `$`-heavy content of the script itself.
  PhRef = "{{REF}}"
  PhFwd = "{{FWD}}"
  PhExtra = "{{EXTRA}}"
  PhOrigin = "{{ORIGIN}}"

  WrapperTemplate* = """#!/bin/bash
# AUTOGENERATED FILE! DO NOT EDIT!
# Generated by update-flatpak-cli for: {{ORIGIN}}

# Unset LD_PRELOAD to silence errors about gtk-nocsd being
# missing from the Flatpak runtime
unset LD_PRELOAD

# Make arguments that are existing paths absolute
# and wrap them in the appropriate type of --file-forwarding
# wrapper tokens.
# (Necessary to make forwarding work reliably)
declare -a args
for arg in "$@"; do
    if [ -e "$arg" ]; then
        args+=("{{FWD}}")
        args+=("$(readlink -f -- "$arg")")
        args+=("@@")
    else
        args+=("$arg")
    fi
done

# Use file forwarding to make paths Just Work
exec flatpak run {{EXTRA}}--file-forwarding "{{REF}}" "${args[@]}"
"""

proc sanitizeForScript(s: string): string =
  ## Neutralise anything that could break out of a double-quoted shell string
  ## or, worse, out of the comment line at the top of the generated file.
  ##
  ## A Flatpak app id cannot legally contain any of these characters, and the
  ## secondary command names come from a compile-time table -- but this code
  ## writes files that are later executed, so the invariant is enforced here
  ## rather than assumed.
  for c in s:
    if c in {'"', '\\', '`', '$', '\n', '\r'} or ord(c) < 32 or ord(c) == 127:
      result.add '_'
    else:
      result.add c

proc renderWrapper*(appRef: string, extraCommand: string, wantsUrls: bool): string =
  ## Build the complete text of a launcher for `appRef`.
  ##
  ## `extraCommand` is a secondary command name (empty for the app's own
  ## `command=`), and `wantsUrls` selects the `@@u ... @@` forwarding tokens
  ## used by applications that take URLs rather than paths.
  let safeRef = sanitizeForScript(appRef)
  let safeExtra = sanitizeForScript(extraCommand)
  let origin =
    if extraCommand.len > 0: safeRef & " --command=" & safeExtra
    else: safeRef
  let extraArgs =
    if extraCommand.len > 0: "--command=" & safeExtra & " "
    else: ""
  let fwdToken = if wantsUrls: "@@u" else: "@@"

  result = WrapperTemplate
  result = result.replace(PhOrigin, origin)
  result = result.replace(PhFwd, fwdToken)
  result = result.replace(PhExtra, extraArgs)
  result = result.replace(PhRef, safeRef)

proc isGeneratedFile*(path: string): bool =
  ## True when `path` is a regular file whose opening lines carry our marker.
  ## Symlinks and special files are never considered ours.
  try:
    if not fileExists(path) or symlinkExists(path):
      return false
    let f = open(path, fmRead)
    defer: f.close()
    # The marker lives in the first two lines, so a short read suffices.
    var head = newString(256)
    let n = f.readBuffer(addr head[0], head.len)
    if n <= 0:
      return false
    let text = head[0 ..< n]
    text.contains(GeneratedMarker)
  except CatchableError:
    false

proc writeLauncher*(path, content: string): bool =
  ## Write `content` to `path` with mode 0755, atomically.
  ##
  ## The write goes to a temporary file in the same directory and is then
  ## renamed over the target, so a crashed or interrupted run can never leave
  ## a truncated launcher that would fail in confusing ways the next time the
  ## command is invoked.
  let dir = parentDir(path)
  let tmp = path & ".tmp" & $getCurrentProcessId()

  try:
    writeFile(tmp, content)
    setFilePermissions(tmp, {fpUserRead, fpUserWrite, fpUserExec,
                             fpGroupRead, fpGroupExec,
                             fpOthersRead, fpOthersExec})
    moveFile(tmp, path)
    true
  except CatchableError:
    if fileExists(tmp):
      try: removeFile(tmp) except CatchableError: discard
    false

proc removeGenerated*(path: string): bool =
  ## Delete a launcher we own.  Refuses anything that is not clearly ours.
  if not isGeneratedFile(path):
    return false
  try:
    removeFile(path)
    true
  except OSError:
    false
